export function ModelPicker({
  models,
  providers,
  value: valueProp,
  defaultValue,
  onValueChange,
  renderProviderMark,
  loading = false,
  disabled = false,
  size = "md",
  side = "bottom",
  align = "start",
  searchPlaceholder = "Search models…",
  showLegend = true,
  open: openProp,
  onOpenChange,
  className,
}: ModelPickerProps) {
  const id = React.useId()
  const [openState, setOpenState] = React.useState(false)
  const open = openProp ?? openState
  const setOpen = (next: boolean) => {
    if (openProp === undefined) setOpenState(next)
    onOpenChange?.(next)
  }

  const [valueState, setValueState] = React.useState(defaultValue ?? models[0]?.id)
  const value = valueProp ?? valueState
  const selected = models.find((m) => m.id === value)

  const [query, setQuery] = React.useState("")
  const [active, setActive] = React.useState<string>()
  const inputRef = React.useRef<HTMLInputElement>(null)
  const listRef = React.useRef<HTMLDivElement>(null)

  const providerList = React.useMemo(() => {
    const list: ModelProvider[] = [...(providers ?? [])]
    for (const m of models) {
      if (!list.some((p) => p.id === m.provider)) list.push({ id: m.provider, name: m.provider })
    }
    return list
  }, [models, providers])

  const groups = React.useMemo(
    () =>
      providerList
        .map((provider) => ({
          provider,
          models: models.filter(
            (m) => m.provider === provider.id && matches(m, provider.name, query.trim()),
          ),
        }))
        .filter((g) => g.models.length > 0),
    [providerList, models, query],
  )
  const flat = React.useMemo(() => groups.flatMap((g) => g.models), [groups])
  const fade = useScrollFade(groups)
  const { ref: fadeRef } = fade
  const setListRef = React.useCallback(
    (el: HTMLDivElement | null) => {
      listRef.current = el
      fadeRef(el)
    },
    [fadeRef],
  )
  const enabled = React.useMemo(() => flat.filter((m) => !m.disabled), [flat])

  // Keep the active option valid as the filter changes.
  React.useEffect(() => {
    if (!open) return
    if (active && enabled.some((m) => m.id === active)) return
    setActive(enabled.find((m) => m.id === value)?.id ?? enabled[0]?.id)
  }, [open, enabled, active, value])

  // Keep it in view. `nearest` never scrolls when it already shows.
  React.useEffect(() => {
    if (!open || !active) return
    const el = listRef.current?.querySelector<HTMLElement>(
      `[data-model-id="${CSS.escape(active)}"]`,
    )
    el?.scrollIntoView({ block: "nearest" })
  }, [open, active])

  const choose = (model: ModelOption) => {
    if (model.disabled) return
    if (valueProp === undefined) setValueState(model.id)
    onValueChange?.(model.id)
    setOpen(false)
  }

  const move = (delta: number) => {
    if (enabled.length === 0) return
    const index = enabled.findIndex((m) => m.id === active)
    const next = (index + delta + enabled.length) % enabled.length
    setActive(enabled[next]?.id)
  }

  const optionId = (modelId: string) => `${id}-option-${modelId}`
  const listId = `${id}-list`

  return (
    <Popover
      open={open}
      onOpenChange={(next) => {
        setOpen(next)
        if (!next) setQuery("")
      }}
    >
      <PopoverTrigger
        disabled={disabled}
        data-slot="model-picker-trigger"
        aria-label={
          selected ? `Model: ${selected.name}` : loading ? "Loading models" : "Choose a model"
        }
        aria-busy={loading || undefined}
        className={cn(
          "chatcn-focus group/model-trigger inline-flex min-w-0 shrink items-center gap-1.5 font-medium whitespace-nowrap select-none",
          "text-(color:--chatcn-fg-muted) hover:bg-(color:--chatcn-fill-hover) hover:text-(color:--chatcn-fg) data-[popup-open]:bg-(color:--chatcn-fill-hover) data-[popup-open]:text-(color:--chatcn-fg)",
          "ease-(--chatcn-ease-standard) transition-[background-color,color,scale] duration-150 active:scale-(--chatcn-press-scale) active:duration-100",
          "disabled:pointer-events-none disabled:opacity-50",
          size === "sm"
            ? "rounded-(--chatcn-radius-sm) text-[0.8125rem]/[1.25rem] h-7 ps-2 pe-1.5"
            : "rounded-(--chatcn-radius-md) text-[0.8125rem]/[1.25rem] h-8 ps-2.5 pe-2",
          "pointer-coarse:h-11",
          className,
        )}
      >
        {selected && renderProviderMark ? (
          <span aria-hidden="true" className="grid size-4 shrink-0 place-items-center">
            {renderProviderMark(selected.provider)}
          </span>
        ) : null}
        {loading && !selected ? <Spinner className="text-(color:--chatcn-fg-subtle)" /> : null}
        <span className="truncate">
          {selected?.name ?? (loading ? "Loading models" : "Choose a model")}
        </span>
        <ChevronDownIcon
          aria-hidden="true"
          className="text-(color:--chatcn-fg-subtle) group-hover/model-trigger:text-(color:--chatcn-fg) size-3.5 shrink-0"
        />
      </PopoverTrigger>

      <PopoverContent
        aria-label="Models"
        side={side}
        align={align}
        // Touch opens on the list so the keyboard does not cover it; everything else searches.
        initialFocus={(type) => (type === "touch" ? true : inputRef.current)}
        data-slot="model-picker-content"
        className="flex w-88 max-w-[calc(100vw-1rem)] flex-col overflow-hidden p-0"
      >
        <div className="border-(color:--chatcn-border) flex h-10 shrink-0 items-center gap-2 border-b px-3">
          <SearchIcon aria-hidden="true" className="text-(color:--chatcn-fg-subtle) size-4 shrink-0" />
          <input
            ref={inputRef}
            value={query}
            onChange={(event) => setQuery(event.target.value)}
            onKeyDown={(event) => {
              if (event.nativeEvent.isComposing) return
              if (event.key === "ArrowDown") {
                event.preventDefault()
                move(1)
              } else if (event.key === "ArrowUp") {
                event.preventDefault()
                move(-1)
              } else if (event.key === "Enter") {
                event.preventDefault()
                const model = enabled.find((m) => m.id === active)
                if (model) choose(model)
              }
            }}
            role="combobox"
            aria-expanded="true"
            aria-controls={listId}
            aria-autocomplete="list"
            aria-activedescendant={active ? optionId(active) : undefined}
            aria-label="Search models"
            placeholder={searchPlaceholder}
            autoComplete="off"
            spellCheck={false}
            className="text-[0.875rem]/[1.25rem] tracking-[-0.003em] text-(color:--chatcn-fg) placeholder:text-(color:--chatcn-fg-subtle) pointer-coarse:text-[1rem]/[1.5rem] pointer-coarse:tracking-[-0.01em] h-full min-w-0 flex-1 bg-transparent outline-none"
          />
        </div>

        <div
          ref={setListRef}
          id={listId}
          role="listbox"
          aria-label="Models"
          onScroll={fade.update}
          data-fade-top={fade.top ? "" : undefined}
          data-fade-bottom={fade.bottom ? "" : undefined}
          className={cn(
            "chatcn-scroll max-h-80 min-h-0 flex-1 scroll-py-1 overflow-y-auto overscroll-contain p-1",
            // The row cut by an edge fades out instead of ending mid-glyph.
            "data-[fade-bottom]:[--chatcn-fade-bottom:24px] data-[fade-top]:[--chatcn-fade-top:24px]",
            "[mask-image:linear-gradient(to_bottom,transparent,#000_var(--chatcn-fade-top,0px),#000_calc(100%-var(--chatcn-fade-bottom,0px)),transparent)]",
          )}
        >
          {loading ? (
            <div className="text-[0.8125rem]/[1.25rem] text-(color:--chatcn-fg-subtle) flex h-24 items-center justify-center gap-2">
              <Spinner />
              Loading models
            </div>
          ) : groups.length === 0 ? (
            <div className="flex flex-col items-center gap-1 px-6 py-8 text-center">
              <SearchXIcon aria-hidden="true" className="text-(color:--chatcn-fg-subtle) mb-1 size-5" />
              <p className="text-[0.8125rem]/[1.25rem] text-(color:--chatcn-fg) font-medium">
                No models match “{query.trim()}”
              </p>
              <p className="text-[0.75rem]/[1rem] text-(color:--chatcn-fg-subtle) text-pretty">
                Try a provider or a capability, like vision.
              </p>
            </div>
          ) : (
            groups.map(({ provider, models: groupModels }) => {
              const labelId = `${id}-group-${provider.id}`
              return (
                // biome-ignore lint/a11y/useSemanticElements: option groups inside a listbox
                <div
                  key={provider.id}
                  role="group"
                  aria-labelledby={labelId}
                  className="not-first:mt-1"
                >
                  <div
                    id={labelId}
                    className="text-[0.75rem]/[1rem] text-(color:--chatcn-fg-subtle) flex h-7 items-center gap-1.5 px-2 font-medium select-none"
                  >
                    {renderProviderMark ? (
                      <span aria-hidden="true" className="grid size-3.5 place-items-center">
                        {renderProviderMark(provider.id)}
                      </span>
                    ) : null}
                    {provider.name}
                  </div>
                  {groupModels.map((model) => {
                    const isSelected = model.id === value
                    const isActive = model.id === active
                    return (
                      // biome-ignore lint/a11y/useKeyWithClickEvents: keys are handled on the combobox input
                      <div
                        key={model.id}
                        id={optionId(model.id)}
                        role="option"
                        aria-selected={isSelected}
                        aria-disabled={model.disabled || undefined}
                        data-model-id={model.id}
                        data-active={isActive ? "" : undefined}
                        tabIndex={-1}
                        onPointerMove={() => {
                          if (!model.disabled && !isActive) setActive(model.id)
                        }}
                        onClick={() => choose(model)}
                        className={cn(
                          "group/model-option rounded-(--chatcn-radius-md) flex cursor-default items-center gap-3 px-2 py-1.5 select-none",
                          "data-[active]:bg-(color:--chatcn-fill-hover) pointer-coarse:min-h-11",
                          model.disabled && "opacity-55",
                        )}
                      >
                        <span className="flex min-w-0 flex-1 flex-col">
                          <span className="flex min-w-0 items-center gap-1.5">
                            <span className="text-[0.875rem]/[1.25rem] tracking-[-0.003em] text-(color:--chatcn-fg) truncate">
                              {model.name}
                            </span>
                            {model.isNew ? (
                              <span className="text-[0.75rem]/[1rem] text-(color:--chatcn-fg-muted) bg-(color:--chatcn-fill) rounded-(--chatcn-radius-xs) shrink-0 px-1.5 leading-[18px] font-medium">
                                New
                              </span>
                            ) : null}
                          </span>
                          {model.disabledReason || model.description ? (
                            <span className="text-[0.75rem]/[1rem] text-(color:--chatcn-fg-subtle) flex min-w-0 items-center gap-1">
                              {model.disabled ? (
                                <LockIcon aria-hidden="true" className="size-3 shrink-0" />
                              ) : null}
                              <span className="truncate">
                                {model.disabled
                                  ? (model.disabledReason ?? model.description)
                                  : model.description}
                              </span>
                            </span>
                          ) : null}
                        </span>
                        {/* Fixed slots, so each capability lines up in its own column. */}
                        {/* Quiet until the row is active: names read first, the footer holds the key. */}
                        <span className="text-(color:--chatcn-fg-faint) group-data-[active]/model-option:text-(color:--chatcn-fg-subtle) flex shrink-0 items-center gap-1.5">
                          {(Object.keys(CAPABILITIES) as ModelCapability[]).map((c) => {
                            const { Icon, label } = CAPABILITIES[c]
                            const has = model.capabilities?.includes(c)
                            return (
                              <span
                                key={c}
                                title={has ? label : undefined}
                                className="grid size-3.5 place-items-center"
                              >
                                {has ? (
                                  <>
                                    <Icon aria-hidden="true" className="size-3.5" />
                                    <span className="sr-only">{label}</span>
                                  </>
                                ) : null}
                              </span>
                            )
                          })}
                        </span>
                        <span
                          aria-hidden="true"
                          className="grid size-4 shrink-0 place-items-center"
                        >
                          {isSelected ? <CheckIcon className="text-(color:--chatcn-fg) size-4" /> : null}
                        </span>
                      </div>
                    )
                  })}
                </div>
              )
            })
          )}
        </div>

        {showLegend ? (
          <div
            aria-hidden="true"
            className="border-(color:--chatcn-border) text-[0.75rem]/[1rem] text-(color:--chatcn-fg-subtle) flex h-9 shrink-0 items-center gap-3 border-t px-3"
          >
            {(Object.keys(CAPABILITIES) as ModelCapability[]).map((c) => {
              const { Icon, label } = CAPABILITIES[c]
              return (
                <span key={c} className="flex items-center gap-1.5">
                  <Icon className="size-3.5" />
                  {label}
                </span>
              )
            })}
          </div>
        ) : null}
      </PopoverContent>
    </Popover>
  )
}

