  {
    id: "atlas",
    name: "Atlas",
    provider: "northwind",
    description: "Fast and strong at code",
    capabilities: ["vision", "tools", "reasoning"],
  },
  {
    id: "meridian-3",
    name: "Meridian 3",
    provider: "meridian",
    description: "Long context for whole repositories",
    capabilities: ["vision", "tools", "reasoning"],
  },
]

/** Made up providers and models, so nothing here reads as a claim about a real product. */
const providers = [
  { id: "northwind", name: "Northwind" },
  { id: "meridian", name: "Meridian" },
]

const iconNode: IconNode = [
  ["path", {"d":"M3 12a9 9 0 1 0 18 0 9 9 0 1 0-18 0"}],
]

const CircleIcon: Icon = /* @__PURE__ */ createIcon("circle", iconNode)

const iconNode2: IconNode = [
  ["path", {"d":"m13 2.68 6.57 3.79a2 2 0 0 1 1 1.73v7.6a2 2 0 0 1-1 1.73L13 21.32a2 2 0 0 1-2 0l-6.57-3.79a2 2 0 0 1-1-1.73V8.2a2 2 0 0 1 1-1.73L11 2.68a2 2 0 0 1 2 0"}],
