/**
 * A model picker for a chat composer: the list opens grouped by provider with capability glyphs,
 * a New tag, a model is picked and the trigger updates, then it opens
 * again for the next one. Loops. Open it yourself and the tour waits for you.
 */
export default function ModelPickerPreview() {
  const [step, setStep] = React.useState({ pick: 0, open: true })
  const [held, hold] = useHold()
  const [mine, setMine] = React.useState<{ value: string; open: boolean } | null>(null)

  React.useEffect(() => {
    if (reducedMotion() || held) return
    setMine(null)
    const id = window.setTimeout(
      () =>
        setStep((s) =>
          s.open ? { pick: (s.pick + 1) % PICKS.length, open: false } : { pick: s.pick, open: true },
        ),
      step.open ? OPEN_MS : CLOSED_MS,
    )
    return () => window.clearTimeout(id)
  }, [step, held])

  const tourValue = PICKS[step.open ? (step.pick + PICKS.length - 1) % PICKS.length : step.pick]!
  const value = mine?.value ?? tourValue
  // A phone sized frame has no room for the list above the composer, so the tour only switches
  // the model there.
  const [short, setShort] = React.useState(() => typeof window !== "undefined" && window.innerHeight < 360)
  React.useEffect(() => {
    const read = () => setShort(window.innerHeight < 360)
    read()
    window.addEventListener("resize", read)
    return () => window.removeEventListener("resize", read)
  }, [])
  const open = mine?.open ?? (step.open && !short)
  // When the tour closes the list, focus returns to the trigger and draws its keyboard ring;
  // nobody used the keyboard, so let it go.
  React.useEffect(() => {
    if (open || mine) return
    const id = window.setTimeout(() => (document.activeElement as HTMLElement | null)?.blur(), 260)
    return () => window.clearTimeout(id)
  }, [open, mine])

  return (
    // Laid out at full size, never scaled: the list opens in a portal that a scaled frame would
    // not shrink, so the composer sits at the bottom and the list opens up from it.
    <div className="flex h-dvh w-full flex-col items-center justify-end gap-3 overflow-hidden p-4">
      <div className="bg-(color:--chatcn-card) shadow-(--chatcn-shadow-sm) rounded-(--chatcn-radius-xl) flex w-full max-w-md flex-col p-3">
        <div className="text-[0.875rem]/[1.25rem] tracking-[-0.003em] text-(color:--chatcn-fg-faint) px-2 pb-5">Ask anything…</div>
        <div className="flex items-center justify-between">
          <ModelPicker
            models={models}
            providers={providers}
            value={value}
            onValueChange={(v) => {
              hold()
              setMine({ value: v, open: false })
            }}
            open={open}
            onOpenChange={(o) => {
              hold()
              setMine({ value, open: o })
            }}
            side="top"
            align="start"
            showLegend={false}
            renderProviderMark={(id) => marks[id]}
          />
          <span
            aria-hidden
            className="bg-(color:--chatcn-fg) text-(color:--chatcn-bg) grid size-8 place-items-center rounded-full"
          >
            <svg viewBox="0 0 16 16" className="size-3.5" fill="none" stroke="currentColor" strokeWidth="1.8">
              <path d="M8 13V3M3.5 7.5 8 3l4.5 4.5" strokeLinecap="round" strokeLinejoin="round" />
            </svg>
          </span>
        </div>
      </div>
      <MoreOn slug="model-picker">Models by provider, with search and capabilities. On</MoreOn>
    </div>
  )
}
